import {PurchaseCancelled, PurchasePending, type ProPurchases} from '../src/pro-purchases';

// This mock is compiled only into the browser harness generated by preview-app.mjs.
export function makePreviewPurchases(): ProPurchases {
  const params = new URLSearchParams(window.location.search);
  let active = params.get('plan') !== 'free';
  let restorable = false;
  const listeners = new Set<(value: boolean) => void>();
  const setActive = (value: boolean) => {
    active = value;
    for (const listener of listeners) listener(active);
  };
  Object.assign(window, { __mockPro: { setActive, setRestorable: (value: boolean) => {restorable=value;} } });
  return {
    async getAccess() { return active; },
    onAccessChange(listener) { listeners.add(listener); return () => { listeners.delete(listener); }; },
    async getOffer() {
      if (params.get('offer') === 'unavailable') return null;
      return {
        price: '¥1,000',
        async purchase() {
          if (params.get('purchase') === 'cancel') throw new PurchaseCancelled();
          if (params.get('purchase') === 'pending') throw new PurchasePending();
          if (params.get('purchase') === 'error') throw new Error('Mock error');
          setActive(true);
          restorable = true;
          return active;
        },
      };
    },
    async restore() {
      if (restorable) setActive(true);
      return active;
    },
  };
}
